import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  describe('list_sessions', () => {
    it('accepts a bare list_sessions frame', () => {
      const result = validateMessage({type: 'list_sessions'});
      expect(result).toEqual({valid: true, data: {type: 'list_sessions'}});
    });

    it('accepts list_sessions with valid limit and before', () => {
      const result = validateMessage({
        type: 'list_sessions',
        limit: 50,
        before: {sessionId: 's1', updatedAt: '2023-01-01T00:00:00Z'},
      });
      expect(result).toEqual({
        valid: true,
        data: {
          type: 'list_sessions',
          limit: 50,
          before: {sessionId: 's1', updatedAt: '2023-01-01T00:00:00Z'},
        },
      });
    });

    it('accepts list_sessions with valid limit and numeric before.updatedAt', () => {
      const result = validateMessage({
        type: 'list_sessions',
        limit: 50,
        before: {sessionId: 's1', updatedAt: 1672531200000},
      });
      expect(result).toEqual({
        valid: true,
        data: {
          type: 'list_sessions',
          limit: 50,
          before: {sessionId: 's1', updatedAt: 1672531200000},
        },
      });
    });

    it('rejects list_sessions with negative limit', () => {
      const result = validateMessage({type: 'list_sessions', limit: -1});
      expect(result).toEqual({valid: false, error: 'limit must be a non-negative integer'});
    });

    it('rejects list_sessions with non-integer limit', () => {
      const result = validateMessage({type: 'list_sessions', limit: 1.5});
      expect(result).toEqual({valid: false, error: 'limit must be a non-negative integer'});
    });

    it('rejects list_sessions with string limit', () => {
      const result = validateMessage({type: 'list_sessions', limit: '10'});
      expect(result).toEqual({valid: false, error: 'limit must be a non-negative integer'});
    });

    it('rejects list_sessions with unparseable before.updatedAt string', () => {
      const result = validateMessage({
        type: 'list_sessions',
        before: {sessionId: 's1', updatedAt: 'not a date'},
      });
      expect(result).toEqual({valid: false, error: 'before.updatedAt must be a valid date string or number'});
    });

    it('rejects list_sessions with missing before.sessionId', () => {
      const result = validateMessage({
        type: 'list_sessions',
        before: {updatedAt: '2023-01-01T00:00:00Z'},
      });
      expect(result).toEqual({valid: false, error: 'before.sessionId must be a string of 1-128 characters'});
    });

    it('rejects list_sessions with empty before.sessionId', () => {
      const result = validateMessage({
        type: 'list_sessions',
        before: {sessionId: '', updatedAt: '2023-01-01T00:00:00Z'},
      });
      expect(result).toEqual({valid: false, error: 'before.sessionId must be a string of 1-128 characters'});
    });

    it('rejects list_sessions with overly long before.sessionId', () => {
      const result = validateMessage({
        type: 'list_sessions',
        before: {sessionId: 'a'.repeat(129), updatedAt: '2023-01-01T00:00:00Z'},
      });
      expect(result).toEqual({valid: false, error: 'before.sessionId must be a string of 1-128 characters'});
    });

    it('drops unknown fields like userId', () => {
      const result = validateMessage({type: 'list_sessions', userId: 'u1'});
      expect(result).toEqual({valid: true, data: {type: 'list_sessions'}});
    });
  });
});

